function Metrics = MeasureFixedPointDesign( ...
    FloatingOutput, FixedOutput, FixedDecimator, ...
    InputFormat, MACFormat, MACData, Parameters)
%% =====================================================
%% MEASURE FIXED-POINT DECIMATOR DESIGN CHARACTERISTICS
%% =====================================================
%
% Coordinates three focused measurements:
%
%   1. Coefficient fixed-point design
%   2. MAC fixed-point design
%   3. Floating-versus-fixed output error
%
% The supporting functions reuse results already generated by the fixed
% decimator. This function does not search for formats or repeat filter-
% response analysis.

    %% ==========================================
    %% SYSTEM SPECIFICATIONS
    %% ==========================================

    Metrics.Specifications.FsDSP = ...
        Parameters.getValue("Fs_DSP");
    Metrics.Specifications.Fpass = ...
        Parameters.getValue("Fpass");
    Metrics.Specifications.Fstop = ...
        Parameters.getValue("Fstop");
    Metrics.Specifications.Apass = ...
        Parameters.getValue("Apass");
    Metrics.Specifications.Astop = ...
        Parameters.getValue("Astop");

    %% ==========================================
    %% FIXED-POINT DESIGN MEASUREMENTS
    %% ==========================================

    Metrics.Coefficient = ...
        MeasureCoefficientFixedPointDesign(FixedDecimator);

    Metrics.MAC = ...
        MeasureMACFixedPointDesign( ...
            InputFormat, MACFormat, MACData);

    Metrics.OutputError = ...
        MeasureFixedPointOutputError( ...
            FloatingOutput, FixedOutput);

    %% ==========================================
    %% COMMAND-WINDOW REPORT
    %% ==========================================

    fprintf('\nFIXED-POINT DECIMATOR DESIGN CHARACTERIZATION\n');

    fprintf('Coefficient format              = Q%d.%d (%d bits)\n', ...
        Metrics.Coefficient.Format.IWL, ...
        Metrics.Coefficient.Format.FWL, ...
        Metrics.Coefficient.Format.WL);

    fprintf('Minimum passing coefficient FWL = %d bits\n', ...
        Metrics.Coefficient.MinimumPassingFWL);

    fprintf('Coefficient RMSE                = %.6g\n', ...
        Metrics.Coefficient.RMSError);

    fprintf('Maximum coefficient error       = %.6g\n', ...
        Metrics.Coefficient.MaximumAbsoluteError);

    fprintf('Product format                  = Q%d.%d (%d bits)\n', ...
        Metrics.MAC.ProductFormat.IWL, ...
        Metrics.MAC.ProductFormat.FWL, ...
        Metrics.MAC.ProductFormat.WL);

    fprintf('Accumulator format              = Q%d.%d (%d bits)\n', ...
        Metrics.MAC.AccumulatorFormat.IWL, ...
        Metrics.MAC.AccumulatorFormat.FWL, ...
        Metrics.MAC.AccumulatorFormat.WL);

    fprintf('Configured headroom             = %d bits\n', ...
        Metrics.MAC.ConfiguredHeadroomBits);

    fprintf('Required accumulator magnitude  = %.6g\n', ...
        Metrics.MAC.RequiredMagnitude);

    fprintf('Observed final-accumulator peak = %.6g\n', ...
        Metrics.MAC.ObservedFinalMaxAbs);

    fprintf('Floating/fixed maximum error    = %.6g\n', ...
        Metrics.OutputError.MaximumAbsoluteError);

    fprintf('Floating/fixed RMS error        = %.6g\n', ...
        Metrics.OutputError.RMSError);

    fprintf('Floating/fixed mean error       = %.6g\n', ...
        Metrics.OutputError.MeanError);

    fprintf('Fixed-point error SNR           = %.3f dB\n', ...
        Metrics.OutputError.ErrorSNRdB);

    fprintf('Overflow events                 = %d\n', ...
        Metrics.MAC.TotalOverflowEventCount);

    fprintf('Arithmetic policy               = %s / %s\n\n', ...
        Metrics.MAC.RoundingMethod, ...
        Metrics.MAC.OverflowAction);
end